// Datadog RUM + Logs shared configuration template.
//
// DO NOT edit this file for local development — it is the CI template.
// config.js is git-ignored; `npm run build` generates _site/config.js from this.
//
// For local development:
//   cp config.template.js config.js
//   # then fill in your applicationId and clientToken
//
// For forks / new deployments:
//   1. Create a Datadog RUM application to get your applicationId + clientToken
//   2. Add DD_APP_ID and DD_CLIENT_TOKEN as GitHub Actions secrets in your repo
//   3. Push to main — the workflow's `npm run build` generates config.js with your values + git SHA version
//
// @see https://docs.datadoghq.com/real_user_monitoring/browser/

window.DD_CONFIG = {
  applicationId: '%%DD_APP_ID%%',
  clientToken:   '%%DD_CLIENT_TOKEN%%',
  site:          'datadoghq.com',
  // A prefix, not the final name: lab-shared.js appends the environment's
  // labs.json id, so each one reports its own service (rum-labs-home,
  // rum-labs-consent, …) under the one application.
  service:       'rum-labs',
  version:       '%%VERSION%%',
  env:           window.location.hostname.endsWith('.github.io') ? 'prod' : 'local',
};
